<?php
require_once dirname(__DIR__).'/includes/bootstrap.php'; require_module('budget');
$pageTitle='Budget List'; $activeMenu='budget-list';
$budgets=db()->query("SELECT b.*,d.name department,c.name category,CONCAT(u.first_name,' ',u.last_name) creator FROM budgets b JOIN departments d ON d.id=b.department_id JOIN budget_categories c ON c.id=b.category_id JOIN users u ON u.id=b.created_by ORDER BY b.id DESC")->fetchAll();
require ROOT_PATH.'/includes/header.php'; ?>
<div class="page-head"><div><h1>Budget Management</h1><p>Control annual budget allocations, ownership and approval status.</p></div><a href="<?= e(url('budget/create.php')) ?>" class="btn btn-primary"><i class="fa-solid fa-plus me-2"></i>Add Budget</a></div>
<div class="card-panel"><div class="card-head"><h2 class="section-title">Budget Register</h2><span class="text-secondary small"><?= count($budgets) ?> records</span></div><div class="card-body"><div class="table-responsive"><table class="table data-table align-middle"><thead><tr><th>Code</th><th>Year</th><th>Department</th><th>Category</th><th>Description</th><th class="text-end">Allocated</th><th>Status</th><th>Created By</th><th>Date</th><th class="no-print">Actions</th></tr></thead><tbody><?php foreach($budgets as $b): ?><tr><td class="fw-bold text-primary"><?= e($b['budget_code']) ?></td><td><?= (int)$b['budget_year'] ?></td><td><?= e($b['department']) ?></td><td><?= e($b['category']) ?></td><td><?= e($b['description']) ?></td><td class="text-end fw-semibold"><?= money($b['allocated_amount']) ?></td><td><?= status_badge($b['approval_status']) ?></td><td><?= e($b['creator']) ?></td><td><?= e(date('M d, Y',strtotime($b['created_at']))) ?></td><td class="no-print"><div class="table-actions"><a class="btn btn-light border" href="<?= e(url('budget/edit.php?id='.$b['id'])) ?>" title="Edit"><i class="fa-solid fa-pen"></i></a><?php if(is_admin() || (role_name()==='Finance Manager' && $b['approval_status']!=='Approved')): ?><a class="btn btn-light border text-danger" data-confirm="Delete this budget record?" href="<?= e(url('budget/delete.php?id='.$b['id'].'&token='.csrf_token())) ?>" title="Delete"><i class="fa-solid fa-trash"></i></a><?php endif; ?></div></td></tr><?php endforeach; ?></tbody></table></div></div></div>
